# components by 8-connectivity and border touch
seen=set(); comps8=[]
for i in range(R):
 for j in range(C):
  if grid[i][j]==8 and (i,j) not in seen:
   q=[(i,j)];seen.add((i,j)); comp=[]
   while q:
    x,y=q.pop();comp.append((x,y))
    for dx in (-1,0,1):
     for dy in (-1,0,1):
      if dx==dy==0: continue
      a,b=x+dx,y+dy
      if 0<=a<R and 0<=b<C and grid[a][b]==8 and (a,b) not in seen: seen.add((a,b));q.append((a,b))
   comps8.append(comp)
[(len(x),(min(a for a,b in x),max(a for a,b in x),min(b for a,b in x),max(b for a,b in x)),any(a in (0,R-1) or b in (0,C-1) for a,b in x)) for x in comps8]
